$ErrorActionPreference='Stop'; $answer=[ordered]@{}; $answer.Computer=$env:COMPUTERNAME; $answer.RunnerProcesses=@(Get-Process XemuTestRunner -ErrorAction SilentlyContinue | Select-Object Id,StartTime,Path); $answer.XemuProcesses=@(Get-Process xemu -ErrorAction SilentlyContinue | Select-Object Id,StartTime,Path); $answer.Listener=@(Get-NetTCPConnection -LocalPort 9368 -State Listen -ErrorAction SilentlyContinue | Select-Object LocalAddress,LocalPort,OwningProcess); try {$w=Invoke-WebRequest -UseBasicParsing -Uri 'http://127.0.0.1:9368/api/v1/status' -TimeoutSec 5; $answer.LocalHttpStatus=$w.StatusCode; $answer.LocalRunnerStatus=($w.Content | ConvertFrom-Json)} catch {$answer.LocalHttpError=$_.Exception.Message}; $answer | ConvertTo-Json -Depth 8
